sealed class PublicContractException: kotlin.Exception() {

    class Rejected(

        val `contractVersion`: kotlin.UInt,

        val `code`: PublicErrorCode,

        val `detail`: kotlin.String
        ) : PublicContractException() {
        override val message
            get() = "contractVersion=${ `contractVersion` }, code=${ `code` }, detail=${ `detail` }"
    }





    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<PublicContractException> {
        override fun lift(error_buf: RustBuffer.ByValue): PublicContractException = FfiConverterTypePublicContractError.lift(error_buf)
    }


}

/**
 * @suppress
 */
public object FfiConverterTypePublicContractError : FfiConverterRustBuffer<PublicContractException> {
    override fun read(buf: ByteBuffer): PublicContractException {


        return when(buf.getInt()) {
            1 -> PublicContractException.Rejected(
                FfiConverterUInt.read(buf),
                FfiConverterTypePublicErrorCode.read(buf),
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: PublicContractException): ULong {
        return when(value) {
            is PublicContractException.Rejected -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterUInt.allocationSize(value.`contractVersion`)
                + FfiConverterTypePublicErrorCode.allocationSize(value.`code`)
                + FfiConverterString.allocationSize(value.`detail`)
            )
        }
    }

    override fun write(value: PublicContractException, buf: ByteBuffer) {
        when(value) {
            is PublicContractException.Rejected -> {
                buf.putInt(1)
                FfiConverterUInt.write(value.`contractVersion`, buf)
                FfiConverterTypePublicErrorCode.write(value.`code`, buf)
                FfiConverterString.write(value.`detail`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




